import {createChatOrchestrator} from './chatOrchestrator.js';
import {PromptBuilder} from '../infrastructure/builders/promptBuilder.js';
import type {AIProvider} from '../types/ai.js';
import type {ChatSession} from '../types/session.js';

// @spec specs/hal-engine-config-hooks/spec.md#8
it('wraps an undefined rejection for onError while preserving the caller rejection', async () => {
  const provider: AIProvider = {
    sendMessage() {
      return {
        [Symbol.asyncIterator]() {
          return this;
        },
        next: () => Promise.reject(undefined),
      };
    },
    async generateStructured<T>(): Promise<T> {
      return {} as T;
    },
  };
  const session: ChatSession = {sessionId: 's1', userId: 'u1', entries: []};
  const errors: Error[] = [];
  const order: string[] = [];
  const orchestrator = createChatOrchestrator(provider, new PromptBuilder({identity: 'Test assistant'}), undefined, {
    hooks: {
      onError: async (_session, error) => {
        errors.push(error);
        order.push('onError');
      },
      afterSession: async () => void order.push('afterSession'),
    },
  });
  const outcome = await orchestrator.processMessage(session).then(
    () => ({rejected: false, value: 'resolved'}),
    (value: unknown) => ({rejected: true, value})
  );

  expect({outcome, order, errors}).toEqual({
    outcome: {rejected: true, value: undefined},
    order: ['onError', 'afterSession'],
    errors: [expect.objectContaining({message: 'undefined', cause: undefined})],
  });
});
EOF
timeout 300 npm test -- --runTestsByPath src/orchestration/chatOrchestrator.rejections.test.ts --runInBand"

